select public.import_products($json$[{"sku":"PCSU-0007594","name":"Bottilons de plongée EQUATOR 2 mm MARES","brand":"MARES","category_path":["plongee","longe-cote-marche-aquatique","equipement-pour-le-longe-cote"],"description":"Bottillons de plongée EQUATOR 2 mm MARESPlongez en eaux chaudes avec le bottillon bas 2 mm en néoprène EQUATOR MARES, souple, léger et pratique pour vos voyages plongée sous les tropiques comme pour vos sorties longe côte.Les bottillons bas de plongée EQUATOR 2 mm MARES sont confortables et souples. En néoprène épaisseur 2 mm, l'EQUATOR MARES est un bottillon bas descendant jusqu'à la cheville.C'est le bottillon idéal pour la pratique de la plongée sous-marine et du snorkeling en eaux chaudes et/ou tropicales mais aussi pour la pratique de longe côte et des activités nautiques.Le bottillon EQUATOR 2 mm MARES est doté d'une semelle en caoutchouc durable pour une protection maximale de vos pieds.Les bottillons de plongée EQUATOR MARES offrent protection thermique et un confort de mouvement maximal.Caractéristiques Bottillons de plongée EQUATOR 2 mm MARESBottillons bas de plongée sous-marine & de snorkelingLéger, idéal pour les voyages en eaux chaudesSemelle antidérapanteEpaisseur 2 mmCompatible avec la pratique du longe-côteInformations techniques :Matériau NéoprèneEpaisseur 2 mmSemelle AntidérapanteType d'eau ChaudeActivité Plongée sous-marine, snorkeling, longe-côteContenu du colis1 x Paire de bottillons bas EQUATOR 2 mm, pointure à choisir.","price_cents":2800,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/PCSU-0007594/01-presentation-412636_equator_boots.jpg"},{"sku":"PCSU-0008395","name":"Combinaison de plongée et d'apnée shorty ALTUM homme 3 mm CRESSI SUB","brand":"CRESSI","category_path":["plongee","nage","combinaisons-de-natation"],"description":"Nagez, plongez, voyagez et randonnez en mer avec le shorty homme ALTUM 3 mm CRESSI SUB, confortable et élégant, ultra-souple & élastique.","price_cents":9500,"compare_at_price_c